"""Assignment-one lecture, grounded in the existing Shipping Lane build.

Never edits the game or the input films. Re-running preserves measured audio.
"""
from pathlib import Path
import json, hashlib, shutil

HERE = Path(__file__).resolve().parent
BOOKS = HERE.parents[2]
GAME = BOOKS / 'walker-claude'
INPUT = GAME / 'youtube/claude-liam-walker-claude-level-one-walkthrough'
ASSIGNMENT = HERE.parents[1] / 'assignments/01-extend-walker-jumpman.md'
SLUG = HERE.name
TITLE = 'Assignment One: Build Walker Claude'
old = json.loads((HERE/'beat_sheet.json').read_text()) if (HERE/'beat_sheet.json').exists() else {'beats':[]}
previous = {b['beat_id']:b for b in old['beats']}
source_sheet = json.loads((INPUT/'beat_sheet.json').read_text())
source_beats = {b['beat_id']:b for b in source_sheet['beats']}
manifest = json.loads((GAME/'evidence/shipping-lane/build-manifest.json').read_text())
sha = lambda p: hashlib.sha256(Path(p).read_bytes()).hexdigest()
for p,h in manifest['runtime_sha256'].items():
    assert sha(GAME/p)==h, 'Game changed since capture: '+p
beats=[]
routes=[]
facts=[]

def add(bid, act, speech, pattern, props, intent, runner='Isometric process drawing', why='The literal source artifact is the teaching evidence.', gate='SHOW', **extra):
    b={'beat_id':bid,'act':act,'lane':'remotion','proof_gate':gate,'narration_text':speech,
       'estimated_duration_s':max(4,len(speech.split())/2.6),'engine':'kokoro','voice':'am_onyx',
       'shot':{'type':'REMOTION','source':'own','visual_intent':intent,
               'motion_claim':'Focus advances through the source-grounded evidence on its spoken cue.',
               'show':[{'at':0,'event':intent},{'at':.3,'event':'First named evidence receives focus'},{'at':.65,'event':'Focus advances to the consequence'}],
               'remotion':{'pattern':pattern,'props':props}},
       'lecture':{'runner_up':runner,'why':why}}
    b.update(extra)
    if bid in previous:
        for k in ['audio_file','actual_duration_s','render_duration_s']:
            if k in previous[bid]: b[k]=previous[bid][k]
    if 'actual_duration_s' in b: props['durationSeconds']=b['actual_duration_s']
    beats.append(b)
    routes.append((bid,act,pattern,runner,why))
    facts.append((bid,intent,props.get('note','Authored bookend / proposed viewer exercise')))
    return b

def table(bid,act,title,speech,rows,source,headers=('Item','Evidence')):
    return add(bid,act,speech,'LectureEvidenceTable',{'title':title,'headers':list(headers),'rows':rows,'note':source,'cues':[.05,.25,.62,.8],'instantReveal':True},title)

def code(bid,act,title,speech,text,source):
    return add(bid,act,speech,'LectureCodeTrace',{'title':title,'code':text,'note':source},title,'Evidence table','The exact expressions explain the visible behavior; line focus preserves their order.')

def pipe(bid,act,title,speech,labels,kinds,note):
    return add(bid,act,speech,'DesignPipelineClaim',{'title':title,'mode':'flow','labels':labels,'objectKinds':kinds,'details':[],'note':note,'diagramStyle':'show-tell-isometric','cues':[.08,.27,.62,.8]},title,'Flat flow diagram','Isometric documents, tools and outputs clarify what is handed off, without posing as an observed interface.')

def footage(bid,act,oldid):
    original=source_beats[oldid]
    (HERE/'media').mkdir(exist_ok=True); (HERE/'audio').mkdir(exist_ok=True)
    shutil.copy2(INPUT/'media'/f'{oldid}.mp4',HERE/'media'/f'{bid}.mp4')
    shutil.copy2(INPUT/original['audio_file'],HERE/'audio'/f'{bid}.wav')
    b={k:v for k,v in original.items() if k not in ['build','audio_file','beat_id','act']}
    b.update(beat_id=bid,act=act,lane='gameplay',proof_gate='SHOW',audio_file=f'audio/{bid}.wav')
    b['shot']['motion_claim']='Actual engine action follows recorded normal inputs; no action retiming.'
    beats.append(b)
    routes.append((bid,act,'Native Godot recording','Isometric reconstruction','Real gameplay, including failures, is the evidence; a reconstruction cannot prove it.'))
    facts.append((bid,original['heading'],'Shipping Lane film, coverage.json and input/state logs'))
    return b

